get-maximum-in-generated-array:
class Solution:
    def getMaximumGenerated(self, n: int) -> int:
        if n < 2:
            return n
        a = [0] * (n + 1)
        a[1] = 1
        best = 1
        for i in range(2, n + 1):
            if i % 2 == 0:
                a[i] = a[i // 2]
            else:
                a[i] = a[i // 2] + a[i // 2 + 1]
            if a[i] > best:
                best = a[i]
        return best

