increasing-decreasing-string:
class Solution:
    def sortString(self, s: str) -> str:
        cnt = {}
        for c in s:
            cnt[c] = cnt.get(c, 0) + 1
        keys = sorted(cnt)
        out = []
        remaining = len(s)
        while remaining:
            for c in keys:
                if cnt[c]:
                    out.append(c)
                    cnt[c] -= 1
                    remaining -= 1
            for c in reversed(keys):
                if cnt[c]:
                    out.append(c)
                    cnt[c] -= 1
                    remaining -= 1
        return ''.join(out)

