largest-triangle-area:
class Solution:
    def largestTriangleArea(self, points: list[list[int]]) -> float:
        best = 0.0
        n = len(points)
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    x1, y1 = points[i]
                    x2, y2 = points[j]
                    x3, y3 = points[k]
                    area = abs((x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1)) / 2.0
                    if area > best:
                        best = area
        return best

