        best = -1
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if (j - i) % 2 == 1:
                    want = 1
                else:
                    want = -1
                if nums[j] - nums[j - 1] != want:
                    break
                ln = j - i + 1
