longest-even-odd-subarray-with-threshold:
class Solution:
    def longestAlternatingSubarray(self, nums: list[int], threshold: int) -> int:
        best = 0
        n = len(nums)
        for l in range(n):
            if nums[l] % 2 != 0 or nums[l] > threshold:
                continue
            r = l
            while r + 1 < n and nums[r + 1] <= threshold and nums[r + 1] % 2 != nums[r] % 2:
                r += 1
            ln = r - l + 1
            if ln > best:
                best = ln
        return best

