class Solution:
    def maximumPopulation(self, logs: list[list[int]]) -> int:
        diff = {}
        for b, d in logs:
            diff[b] = diff.get(b, 0) + 1
            diff[d] = diff.get(d, 0) - 1
        best = 0
        best_year = 0
        cur = 0
        for y in range(1950, 2051):
            cur += diff.get(y, 0)
            if cur > best:
                best = cur
                best_year = y
        return best_year

