relative-ranks:
class Solution:
    def findRelativeRanks(self, score: list[int]) -> list[str]:
        order = sorted(range(len(score)), key=lambda i: -score[i])
        out = [''] * len(score)
        medal = {0: 'Gold Medal', 1: 'Silver Medal', 2: 'Bronze Medal'}
        for rank, i in enumerate(order):
            out[i] = medal.get(rank, str(rank + 1))
        return out

relative-sort-array:
class Solution:
    def relativeSortArray(self, arr1: list[int], arr2: list[int]) -> list[int]:
        cnt = {}
        for v in arr1:
            cnt[v] = cnt.get(v, 0) + 1
        out = []
        for v in arr2:
            if cnt.get(v, 0):
                out.extend([v] * cnt[v])
                cnt[v] = 0
        for v in sorted(cnt):
            if cnt[v]:
                out.extend([v] * cnt[v])
        return out

