prime-arrangements:
class Solution:
    def numPrimeArrangements(self, n: int) -> int:
        def is_prime(x):
            if x < 2:
                return False
            d = 2
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 1
            return True
        p = 0
        for x in range(1, n + 1):
            if is_prime(x):
                p += 1
        mod = 10 ** 9 + 7
        res = 1
        for x in range(2, p + 1):
            res = res * x % mod
        for x in range(2, n - p + 1):
            res = res * x % mod
        return res

