class Solution:
    def projectionArea(self, grid: list[list[int]]) -> int:
        n = len(grid)
        top = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j]:
                    top += 1
        side = 0
        for row in grid:
            side += max(row)
        front = 0
        for j in range(n):
            front += max(grid[i][j] for i in range(n))
        return top + side + front

