        R, C = len(grid), len(grid[0])
        def dfs(i, j):
            if i < 0 or j < 0 or i >= R or j >= C or grid[i][j] == '0': return
            grid[i][j] = '0'
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                dfs(i+di, j+dj)
        ans = 0
        for i in range(R):
            for j in range(C):
                if grid[i][j] == '1':
                    ans += 1
                    dfs(i, j)
        return ans

