    def diagonalPrime(self, nums: List[List[int]]) -> int:
        def isp(x):
            if x < 2: return False
            if x % 2 == 0: return x == 2
            i = 3
            while i * i <= x:
                if x % i == 0: return False
                i += 2
            return True
        best = 0
        n = len(nums)
        for i in range(n):
            for v in (nums[i][i], nums[i][n - 1 - i]):
                if isp(v):
                    best = max(best, v)
        return best

