time-needed-to-buy-tickets:
from typing import List
class Solution:
    def timeRequiredToBuy(self, tickets: List[int], k: int) -> int:
        t = 0
        for i, x in enumerate(tickets):
            if i <= k:
                t += min(x, tickets[k])
            else:
                t += min(x, tickets[k] - 1)
        return t

