class Solution:
    def minimumMoves(self, s: str) -> int:
        i = 0
        moves = 0
        while i < len(s):
            if s[i] == 'X':
                moves += 1
                i += 3
            else:
                i += 1
        return moves

find-the-middle-index-in-array:
from typing import List
class Solution:
    def findMiddleIndex(self, nums: List[int]) -> int:
        total = sum(nums)
        left = 0
        for i, x in enumerate(nums):
            if left == total - left - x:
                return i
            left += x
        return -1

minimum-time-to-type-word-using-special-:
class Solution:
    def minTimeToType(self, word: str) -> int:
        cur = 'a'
        t = 0
        for c in word:
            d = abs(ord(c) - ord(cur))
            t += min(d, 26 - d) + 1
            cur = c
        return t
